const { chromium } = require('playwright');

(async () => {
  const browser = await chromium.launch({ headless: false });
  const page = await browser.newPage();

  const baseDir = 'C:/Users/Manu/Projects/pokemon_database_agentic/agents/20dbe011/e2e_test_runner_0_0/img/pokemon-e2e-tests';

  try {
    // 1. Homepage
    await page.goto('http://localhost:3000');
    await page.waitForLoadState('networkidle');
    await page.screenshot({ path: `${baseDir}/01_homepage.png`, fullPage: true });
    console.log('Screenshot 1: Homepage captured');

    // 2. Search for Pikachu
    await page.fill('input[type="text"]', 'pikachu');
    await page.screenshot({ path: `${baseDir}/02_search_input.png`, fullPage: true });
    console.log('Screenshot 2: Search input captured');

    // 3. Search results
    await page.click('button:has-text("Search")');
    await page.waitForTimeout(2000);
    await page.screenshot({ path: `${baseDir}/03_search_results.png`, fullPage: true });
    console.log('Screenshot 3: Search results captured');

    // 4. Pokemon detail view
    await page.click('text=pikachu');
    await page.waitForTimeout(2000);
    await page.screenshot({ path: `${baseDir}/04_pokemon_detail.png`, fullPage: true });
    console.log('Screenshot 4: Pokemon detail captured');

    // 5. Toggle shiny sprite
    const img = await page.locator('img[alt*="pikachu"]').first();
    await img.click();
    await page.waitForTimeout(500);
    await page.screenshot({ path: `${baseDir}/05_shiny_sprite.png`, fullPage: true });
    console.log('Screenshot 5: Shiny sprite captured');

    // 6. Search with partial name
    await page.fill('input[type="text"]', 'char');
    await page.click('button:has-text("Search")');
    await page.waitForTimeout(2000);
    await page.screenshot({ path: `${baseDir}/06_partial_search.png`, fullPage: true });
    console.log('Screenshot 6: Partial search captured');

    console.log('All screenshots captured successfully');
  } catch (error) {
    console.error('Error capturing screenshots:', error);
  } finally {
    await browser.close();
  }
})();

